 DROP TABLE IF EXISTS COUNTRY_CODES; 

CREATE TABLE COUNTRY_CODES (
    COUNTRY VARCHAR (100),
    ISO2 VARCHAR (2),
    ISO3 VARCHAR (3),
    COUNTRY_CODE INT,
    ISO_3166_2 VARCHAR(15),
    REGION_CODE VARCHAR(3),
    SUBREGION_CODE VARCHAR(3),
    REGION_TEXT_EN VARCHAR(50),
    REGION_TEXT_DE VARCHAR(50),
    SUBREGION_TEXT_EN VARCHAR(50),
    SUBREGION_TEXT_DE VARCHAR(50)
);
     
